'use client'

import { useEffect, useId, useRef, useState, type ReactNode } from 'react'
import './process-timeline.css'

export interface ProcessTimelineStep {
  id: string
  title: string
  description: string
  duration?: string
  deliverables?: string[]
  /** Decorative artwork. Put essential information in the text fields. */
  media: ReactNode
}

export interface ProcessTimelineProps {
  steps: ProcessTimelineStep[]
  title?: string
  className?: string
}

function decorativeMedia(element: HTMLDivElement | null) {
  element?.setAttribute('inert', '')
}

function scrollParent(element: HTMLElement) {
  let parent = element.parentElement
  while (parent) {
    if (/(auto|scroll|overlay)/.test(window.getComputedStyle(parent).overflowY)) return parent
    parent = parent.parentElement
  }
  return null
}

/** A readable project process with a scroll-following decorative preview. */
export function ProcessTimeline({ steps, title = 'From first thought to launch', className = '' }: ProcessTimelineProps) {
  const headingId = useId()
  const rootRef = useRef<HTMLElement>(null)
  const stepRefs = useRef<(HTMLLIElement | null)[]>([])
  const [activeId, setActiveId] = useState<string | null>(null)
  const activeIndex = Math.max(0, steps.findIndex((step) => step.id === activeId))
  const activeStep = steps[activeIndex]

  useEffect(() => {
    const element = rootRef.current
    if (!element || !steps.length) return
    const viewport = scrollParent(element)
    const scrollTarget = viewport ?? window
    let frame = 0

    function readPosition() {
      frame = 0
      const bounds = viewport?.getBoundingClientRect()
      const top = Math.max(0, bounds?.top ?? 0)
      const bottom = Math.min(window.innerHeight, bounds?.bottom ?? window.innerHeight)
      if (bottom <= top) return
      const componentBounds = element!.getBoundingClientRect()
      if (componentBounds.bottom < top || componentBounds.top > bottom) return
      const target = top + Math.min(80, (bottom - top) * 0.22)
      let next = 0
      for (let index = 0; index < steps.length; index += 1) {
        const step = stepRefs.current[index]
        if (step && step.getBoundingClientRect().top <= target) next = index
      }
      // A short final stage may never reach the top threshold before the scroll ends.
      const lastBounds = stepRefs.current[steps.length - 1]?.getBoundingClientRect()
      if (lastBounds && lastBounds.top < bottom && lastBounds.bottom <= bottom + 1) next = steps.length - 1
      setActiveId((current) => current === steps[next].id ? current : steps[next].id)
    }

    function scheduleRead() {
      if (!frame) frame = window.requestAnimationFrame(readPosition)
    }

    readPosition()
    scrollTarget.addEventListener('scroll', scheduleRead, { passive: true })
    // Page scrolling can move a nested viewport into or out of view.
    if (viewport) window.addEventListener('scroll', scheduleRead, { passive: true })
    window.addEventListener('resize', scheduleRead)
    const resize = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(scheduleRead)
    resize?.observe(element)
    if (viewport) resize?.observe(viewport)
    return () => {
      scrollTarget.removeEventListener('scroll', scheduleRead)
      if (viewport) window.removeEventListener('scroll', scheduleRead)
      window.removeEventListener('resize', scheduleRead)
      resize?.disconnect()
      window.cancelAnimationFrame(frame)
    }
  }, [steps])

  return (
    <section ref={rootRef} className={`ac-process ${className}`.trim()} aria-labelledby={headingId}>
      <header className="ac-process-heading">
        <div><span className="ac-process-eyebrow">THE PROCESS</span><h2 id={headingId}>{title}</h2></div>
        <span className="ac-process-total">{steps.length.toString().padStart(2, '0')} stages</span>
      </header>
      {activeStep ? <div className="ac-process-layout">
        <ol className="ac-process-steps">
          {steps.map((step, index) => <li
            key={step.id}
            ref={(element) => { stepRefs.current[index] = element }}
            className="ac-process-step"
            aria-current={activeIndex === index ? 'step' : undefined}
          >
            <div className="ac-process-step-meta"><span className="ac-process-number" aria-hidden="true">{(index + 1).toString().padStart(2, '0')}</span>{step.duration && <span>{step.duration}</span>}</div>
            <h3>{step.title}</h3>
            <p>{step.description}</p>
            {!!step.deliverables?.length && <ul className="ac-process-deliverables" aria-label={`${step.title} deliverables`}>{step.deliverables.map((deliverable, itemIndex) => <li key={`${itemIndex}-${deliverable}`}>{deliverable}</li>)}</ul>}
            <div ref={decorativeMedia} className="ac-process-inline-art" aria-hidden="true">{step.media}</div>
          </li>)}
        </ol>
        <div ref={decorativeMedia} className="ac-process-preview" aria-hidden="true">
          <div key={activeStep.id} className="ac-process-preview-art">{activeStep.media}</div>
          <div className="ac-process-preview-caption"><span>{activeStep.title}</span><span>{(activeIndex + 1).toString().padStart(2, '0')} / {steps.length.toString().padStart(2, '0')}</span></div>
          <div className="ac-process-progress"><span style={{ width: `${((activeIndex + 1) / steps.length) * 100}%` }} /></div>
        </div>
      </div> : <p className="ac-process-empty">The next chapter is taking shape. Process details are coming soon.</p>}
    </section>
  )
}

.ac-process {
  --ac-process-ink: #272d25;
  --ac-process-muted: #71776d;
  --ac-process-line: #d6dacf;
  --ac-process-accent: #536d3f;
  --ac-process-surface: #e9eddf;
  --ac-process-radius: 4px;
  container-type: inline-size;
  container-name: ac-process;
  width: 100%;
  color: var(--ac-process-ink);
  font-family: inherit;
  font-size: 14px;
  text-align: left;
}
.ac-process, .ac-process::before, .ac-process::after, .ac-process *, .ac-process *::before, .ac-process *::after { box-sizing: border-box; }
.ac-process-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; margin-bottom: 32px; }
.ac-process-eyebrow { display: block; margin-bottom: 15px; color: var(--ac-process-muted); font-size: 10px; line-height: 1.5; letter-spacing: .14em; }
.ac-process-heading h2 { max-width: 15ch; margin: 0; font-size: clamp(28px, 5.6cqw, 48px); font-weight: 500; line-height: 1.04; letter-spacing: -.055em; overflow-wrap: anywhere; }
.ac-process-total { flex-shrink: 0; padding-bottom: 3px; color: var(--ac-process-muted); font-size: 10px; font-variant-numeric: tabular-nums; }
.ac-process-layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, .95fr); align-items: start; gap: 40px; }
.ac-process-steps { list-style: none; margin: 0; padding: 0; }
.ac-process-step { position: relative; min-height: 260px; margin: 0; padding: 24px 0 35px; border-top: 1px solid var(--ac-process-line); }
.ac-process-step::before { position: absolute; top: -1px; left: 0; width: 26px; height: 2px; background: var(--ac-process-accent); content: ''; transform: scaleX(0); transform-origin: left; transition: transform .22s; }
.ac-process-step[aria-current=step]::before { transform: scaleX(1); }
.ac-process-step-meta { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 17px; color: var(--ac-process-muted); font-size: 10px; line-height: 1.5; }
.ac-process-number { color: var(--ac-process-accent); font-variant-numeric: tabular-nums; }
.ac-process-step h3 { margin: 0 0 13px; font-size: clamp(24px, 4cqw, 34px); font-weight: 500; letter-spacing: -.045em; line-height: 1.1; overflow-wrap: anywhere; }
.ac-process-step p { max-width: 44ch; margin: 0; color: var(--ac-process-muted); font-size: 13px; line-height: 1.7; overflow-wrap: anywhere; }
.ac-process-deliverables { display: flex; flex-wrap: wrap; gap: 6px; list-style: none; margin: 20px 0 0; padding: 0; }
.ac-process-deliverables li { padding: 5px 8px; border: 1px solid var(--ac-process-line); border-radius: 3px; font-size: 9px; line-height: 1.4; overflow-wrap: anywhere; }
.ac-process-preview { position: sticky; top: 16px; overflow: hidden; border-radius: var(--ac-process-radius); background: var(--ac-process-surface); pointer-events: none; }
.ac-process-preview-art { aspect-ratio: 4 / 5; overflow: hidden; animation: ac-process-arrive .28s ease-out both; }
.ac-process-preview-art > *, .ac-process-inline-art > * { display: block; width: 100%; height: 100%; object-fit: cover; }
.ac-process-preview-caption { display: flex; justify-content: space-between; gap: 14px; padding: 13px 14px; font-size: 10px; line-height: 1.5; font-variant-numeric: tabular-nums; }
.ac-process-preview-caption span:last-child { color: var(--ac-process-muted); }
.ac-process-progress { height: 3px; background: var(--ac-process-line); }
.ac-process-progress span { display: block; height: 100%; background: var(--ac-process-accent); transition: width .25s ease; }
.ac-process-inline-art { display: none; overflow: hidden; pointer-events: none; }
.ac-process-empty { margin: 0; padding: 30px 0; border-top: 1px solid var(--ac-process-line); color: var(--ac-process-muted); line-height: 1.7; }
@container ac-process (max-width: 560px) {
  .ac-process-layout { grid-template-columns: minmax(0, 1fr); gap: 0; }
  .ac-process-heading { gap: 15px; margin-bottom: 24px; }
  .ac-process-heading h2 { font-size: clamp(26px, 7cqw, 38px); }
  .ac-process-eyebrow { font-size: 8px; margin-bottom: 12px; }
  .ac-process-total { font-size: 9px; }
  .ac-process-step { min-height: 220px; padding-block: 22px 28px; }
  .ac-process-step h3 { font-size: 28px; }
  .ac-process-step p { max-width: 50ch; font-size: 12px; }
  .ac-process-preview { display: none; }
  .ac-process-inline-art { display: block; height: 220px; margin-top: 24px; border-radius: var(--ac-process-radius); background: var(--ac-process-surface); }
}
@container ac-process (max-width: 300px) {
  .ac-process-total { display: none; }
  .ac-process-inline-art { height: 190px; }
  .ac-process-deliverables { gap: 5px; }
  .ac-process-deliverables li { padding: 5px 7px; font-size: 8px; }
}
@keyframes ac-process-arrive { from { opacity: .4; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
@media (prefers-reduced-motion: reduce) {
  .ac-process-preview-art { animation: none; }
  .ac-process-progress span, .ac-process-step::before { transition: none; }
}
